package example;

// Dummy interfaces/classes to satisfy compilation without actual Eclipse JDT types
interface IPackageFragment { }
interface IPackageFragmentRoot {
    IPackageFragment createPackageFragment(String name, boolean b, Object o);
}

class AbstractEclipseJava { 
    // Mimic the field *before* it became private in the commit
    public IPackageFragmentRoot fSourceFolder = new IPackageFragmentRoot() {
        @Override
        public IPackageFragment createPackageFragment(String name, boolean b, Object o) {
            return null; // Dummy implementation
        }
    };
    // The getter introduced in the commit, which the rule will use
    public IPackageFragmentRoot getfSourceFolder() {
        return fSourceFolder;
    }
}

public class MyClass {
    private AbstractEclipseJava context = new AbstractEclipseJava();

    public void testMethod() {
        IPackageFragment pack = context.fSourceFolder.createPackageFragment("test1", false, null);
    }
}

