negativeExample:
package example;

interface IPackageFragment { }
interface IPackageFragmentRoot {
    IPackageFragment createPackageFragment(String name, boolean b, Object o);
}

// A different class with the same field name, but not an instance of AbstractEclipseJava
class AnotherClass {
    public IPackageFragmentRoot fSourceFolder = new IPackageFragmentRoot() {
        @Override public IPackageFragment createPackageFragment(String name, boolean b, Object o) { return null; }
    };
}

class AbstractEclipseJava { 
    public IPackageFragmentRoot fSourceFolder = new IPackageFragmentRoot() {
        @Override public IPackageFragment createPackageFragment(String name, boolean b, Object o) { return null; }
    };
    public IPackageFragmentRoot getfSourceFolder() { return fSourceFolder; }
}

public class MyClassNegative {
    private AnotherClass otherContext = new AnotherClass();

    public void testDifferentClassFieldAccess() {
        // This should NOT match because 'otherContext' is not an 'AbstractEclipseJava'
        IPackageFragment pack = otherContext.fSourceFolder.createPackageFragment("test1", false, null);
    }
}

